function resolveBrochureImage(fileStr) {
  if (!fileStr) return "/assets/core/icons/search.webp";
  if (fileStr.startsWith("/assets/")) return fileStr;
  const base = fileStr.split("/").pop();
  return IMAGE_PATH_MAP[fileStr] || IMAGE_PATH_MAP[base] || `/assets/plants/food/${base}`;
}
const PDF = '/turnkey-brochures/pdfs'

function pdfHref(filename) {
  return `${PDF}/${encodeURIComponent(filename)}`
}

